"1009461": {"exam": "AI-103", "n": 104, "kind": "select", "area": "data/img/ai-103/image64.png", "blocks": [{"type": "code", "text": "def get_self_harm_severity (comment: str) -> int:\n     key = os.environ[\"CONTENT_SAFETY_KEY\"]\n     endpoint = os.environ\n[\"CONTENT_SAFETY_ENDPOINT\"]\n     client = ContentSafetyClient(endpoint,\nAzureKeyCredential(key))\n     request = {{0}}\n     response = {{1}}\n     result = next(\n               item for item in response.categories_analysis\n               if item.category == TextCategory.SELF_HARM\n\n          )\n          return result.severity", "slots": [{"options": ["AnalyzeTextOptions(categories=comment)", "AnalyzeTextOptions(text=[comment])", "AnalyzeTextOptions(text=comment)", "TextCategory.SELF_HARM(comment)"], "answer": "AnalyzeTextOptions(text=comment)"}, {"options": ["client.analyze_image(request)", "client.analyze_text(request)", "client.moderate_text(request)", "client.path(\"/text:analyze\").post(request)"], "answer": "client.analyze_text(request)"}]}]},
"1009464": {"exam": "AI-103", "n": 107, "kind": "yesno", "area": "data/img/ai-103/image67.png", "exhibits": {"data/img/ai-103/image66.png": [{"type": "code", "text": "sample_text = \"Contact John Doe at 312-555-1234 or\njohn.doe@contoso.com. His SSN is 859-98-0987.\"\n\ndef redact_for_model(input_text):\n     payload = {\n          \"kind\": \"PiiEntityRecognition\",\n          \"parameters\": {\n               \"modelVersion\": \"latest\",\n               \"piiCategories\": [\"Person\", \"PhoneNumber\"],\n               \"redactionPolicies\": [\n                    {\n                         \"policyKind\": \"entityMask\"\n                    }\n               ]\n          },\n          \"analysisInput\": {\n              \"documents\": [\n               {\n                    \"id\": \"1\",\n                    \"language\": \"en\",\n                    \"text\": input_text\n                    }\n               ]\n          }\n     }\n…\n     return {\n          \"text for model\": doc.get(\"redactedText\", \"\"),\n          \"audit\": [\n               (entity[\"text\"], entity[\"category\"], entity\n[\"confidenceScore\"])\n               for entity in doc[\"entities\"]\n          ]\n     }\nresult = redact_for_model(sample_text)"}]}, "head": ["Statements"], "blocks": [{"type": "row", "label": "For sample_text, audit will include entity records for Contact and SSN.", "answer": "No"}, {"type": "row", "label": "For sample_text, text_for_model will include john.doe@contoso.com and 859-98-0987.", "answer": "Yes"}, {"type": "row", "label": "For sample_text, text_for_model will contain entity type masks for John Doe and 312-555-1234.", "answer": "Yes"}], "note": "The exhibit code uses the key \"text for model\" (with spaces) while the statements say text_for_model; both kept as shown. The code terms in the statements are monospace in the image."},
